extensibilityCode.vanilla:
// Drawer com direção customizada. Além do gatilho, a gaveta abre e fecha por
// código; fechar por chamada informa o motivo `api`, que separa no analytics a
// gaveta que alguém dispensou da que o programa recolheu.
const gaveta = createDrawer({
  trigger: botaoAbrir,
  direction: 'right',
  content: corpo,
  class: 'nds-max-w-md',
  onOpenChange: (aberto) => registrarEstado(aberto),
  onClose: (motivo) => registrarSaida(motivo),   // escape | overlay | close-button | api
});

gaveta.open();
gaveta.toggle();
if (gaveta.isOpen()) gaveta.close();

customizationCode.web:
/* Override de overlay para tema custom */
[data-slot='drawer-overlay'] {
  background-color: hsl(var(--background) / 0.6);
  backdrop-filter: blur(8px);
}

